import React from "react";
import { Grid, Skeleton } from "@mui/material";
import FormInputText from "components/form/FormInputText";
import FormInputSelect from "components/form/FormInputSelect";

const ApplicationCurrentAddress = ({
  disabled,
  control,
  setValue,
  addressCities,
  addressCitiesLoading,
  addressDistricts,
  addressDistrictsLoading,
  addressStateLoading,
  addressStates,
  addressTownshipLoading,
  addressVillageLoading,
  addressVillages,
  addressVillageTracts,
  addressVillageTractsLoading,
  addressWards,
  addressWardsLoading,
  addressTownshipsArr,
}) => {
  return (
    <Grid
      container
      item
      spacing={2}
      xs={12}
      sm={6}
      justifyContent="flex-start"
      alignItems="flex-start"
    >
      <Grid item xs={12}>
        {" "}
        <label style={{ fontWeight: "bold" }}>Current Address</label>
      </Grid>
      <Grid item xs={12}></Grid>
      <Grid item xs={12}>
        {addressStateLoading ? (
          <Skeleton variant="rectangular" height={37.13} />
        ) : (
          <FormInputSelect
            control={control}
            options={addressStates}
            getOptionLabel={(option) => option?.name}
            id="id"
            name="current_state_id"
            label="State"
            disabled={disabled}
            onSelect={() => {
              setValue("current_district_id", "");
              setValue("current_township_id", "");
              setValue("current_city_id", "");
              setValue("current_ward_id", "");
              setValue("current_village_tract_id", "");
              setValue("current_village_id", "");
            }}
          />
        )}
      </Grid>
      <Grid item xs={12}>
        {addressDistrictsLoading ? (
          <Skeleton variant="rectangular" height={37.13} />
        ) : (
          <FormInputSelect
            control={control}
            options={addressDistricts}
            getOptionLabel={(option) => option?.name}
            id="id"
            name="current_district_id"
            label="District"
            disabled={disabled}
            onSelect={() => {
              setValue("current_township_id", "");
              setValue("current_city_id", "");
              setValue("current_ward_id", "");
              setValue("current_village_tract_id", "");
              setValue("current_village_id", "");
            }}
          />
        )}
      </Grid>
      <Grid item xs={12}>
        {addressTownshipLoading ? (
          <Skeleton variant="rectangular" height={37.13} />
        ) : (
          <FormInputSelect
            control={control}
            options={addressTownshipsArr}
            getOptionLabel={(option) => option?.name}
            id="id"
            name="current_township_id"
            label="Township"
            disabled={disabled}
            onSelect={() => {
              setValue("current_city_id", "");
              setValue("current_ward_id", "");
              setValue("current_village_tract_id", "");
              setValue("current_village_id", "");
            }}
          />
        )}
      </Grid>
      <Grid item xs={12}>
        {addressCitiesLoading ? (
          <Skeleton variant="rectangular" height={37.13} />
        ) : (
          <FormInputSelect
            control={control}
            options={addressCities}
            getOptionLabel={(option) => option?.name}
            id="id"
            name="current_city_id"
            label="City"
            disabled={disabled}
            onSelect={() => {
              setValue("current_ward_id", "");
              setValue("current_village_tract_id", "");
              setValue("current_village_id", "");
            }}
          />
        )}
      </Grid>
      <Grid item xs={12}>
        {addressWardsLoading ? (
          <Skeleton variant="rectangular" height={37.13} />
        ) : (
          <FormInputSelect
            control={control}
            options={addressWards}
            getOptionLabel={(option) => option?.name}
            id="id"
            name="current_ward_id"
            label="Ward"
            disabled={disabled}
            onSelect={() => {
              setValue("current_village_tract_id", "");
              setValue("current_village_id", "");
            }}
          />
        )}
      </Grid>
      <Grid item xs={12}>
        {addressVillageTractsLoading ? (
          <Skeleton variant="rectangular" height={37.13} />
        ) : (
          <FormInputSelect
            control={control}
            options={addressVillageTracts}
            getOptionLabel={(option) => option?.name}
            id="id"
            name="current_village_tract_id"
            label="Village Tract"
            disabled={disabled}
            onSelect={() => {
              setValue("current_village_id", "");
            }}
          />
        )}
      </Grid>
      <Grid item xs={12}>
        {addressVillageLoading ? (
          <Skeleton variant="rectangular" height={37.13} />
        ) : (
          <FormInputSelect
            control={control}
            options={addressVillages}
            getOptionLabel={(option) => option?.name}
            id="id"
            name="current_village_id"
            label="Village"
            disabled={disabled}
          />
        )}
      </Grid>
      <Grid item xs={12}>
        <FormInputText
          multiline
          control={control}
          label="Street/Road"
          name="current_road_street"
          disabled={disabled}
          sx={{
            pt: 1,
            textarea: {
              minHeight: "80px",
              maxHeight: "80px",
              overflow: "auto !important",
            },
          }}
        />
      </Grid>
      <Grid item xs={12}>
        <FormInputText
          multiline
          control={control}
          label="Full Address"
          name="current_full_address"
          disabled
          sx={{
            pt: 1,
            textarea: {
              minHeight: "100px",
              maxHeight: "100px",
              overflow: "auto !important",
            },
          }}
        />
      </Grid>
    </Grid>
  );
};

export default React.memo(ApplicationCurrentAddress);
